import Link from 'next/link';
import { BarChart3, Boxes, Clock3, GalleryVerticalEnd, Layers3, ShoppingBag, Sparkles } from 'lucide-react';

import { AdminGridLink, AdminMetric, AdminPage, AdminPageHeader, AdminPanel } from '@/features/admin/components';
import { getVendorAccess } from '@/features/vendor/auth/vendorAccess';
import { prisma } from '@/lib/prisma';

export default async function VendorOverviewPage(){const access=await getVendorAccess();const [products,media,campaigns,collections,promotions,pending]=await Promise.all([prisma.product.count({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id,status:{not:'ARCHIVED'}}}),prisma.mediaAsset.count({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id,status:'ACTIVE'}}),prisma.storeStudioCampaign.count({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id,status:{not:'EXPIRED'}}}),prisma.storeCollection.count({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id,status:{not:'ARCHIVED'}}}),prisma.promotion.count({where:{workspaceId:access.workspace.id,vendorProfileId:access.vendor.id,status:{not:'ARCHIVED'}}}),prisma.adminApprovalRequest.count({where:{workspaceId:access.workspace.id,requestedById:access.session.user.id,status:'PENDING'}})]);return <AdminPage><div className="mx-auto max-w-[96rem] space-y-5"><AdminPageHeader eyebrow="Vendor Studio" title={access.vendor.name} description="Manage your catalog and campaigns inside AJ Logik. Every public change remains subject to workspace approval."/><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><AdminMetric icon={Boxes} label="Products" value={products}/><AdminMetric icon={GalleryVerticalEnd} label="Media assets" value={media}/><AdminMetric icon={Sparkles} label="Campaigns" value={campaigns}/><AdminMetric icon={Clock3} label="Pending approvals" value={pending}/></section><AdminPanel title="Studios" description="Each Studio shares the same vendor ownership, Media Gallery and approval boundary."><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><AdminGridLink href="/vendor/products" icon={Boxes} title="Product Studio" description="Products, galleries, variants and stock." meta={`${products} records`}/><AdminGridLink href="/vendor/media" icon={GalleryVerticalEnd} title="Media Studio" description="Upload and reuse your images and videos." meta={`${media} assets`}/><AdminGridLink href="/vendor/collections" icon={Layers3} title="Collection Studio" description="Assemble your published products into discovery groups." meta={`${collections} collections`}/><AdminGridLink href="/vendor/promotions" icon={ShoppingBag} title="Promotion Studio" description="Submit controlled offers for your catalog." meta={`${promotions} promotions`}/><AdminGridLink href="/vendor/stories" icon={Sparkles} title="Stories" description="Build independent Story campaigns from uploaded media."/><AdminGridLink href="/vendor/reels" icon={Sparkles} title="Reels" description="Build independent portrait-video campaigns."/><AdminGridLink href="/vendor/analytics" icon={BarChart3} title="Analytics" description="Review activity associated with your products and campaigns."/></div></AdminPanel><div className="rounded-[2rem] border border-border/60 bg-card/70 p-5 text-xs leading-5 text-muted-foreground"><strong className="text-foreground">Commerce mode:</strong> {access.workspace.commerceMode.replaceAll('_',' ')}. Only the Rcentz Developer Admin can change this platform capability.</div></div></AdminPage>}
